inject_theme_polish()

# ── HBlock-2: TERM / SUBJECT / MANUAL ────────────────────────────────────────
# Streamlit clears a widget's key-bound session_state entry whenever that
# widget isn't rendered during a script run (e.g. after switch_page() to a
# different page and back) — so relying on key= alone silently reset Term/
# Subject/Manual back to their defaults every time a cadet returned to the
# dashboard. Plain (non-widget) session_state assignments don't get cleared
# that way, so the selection is separately mirrored into *_PERSIST keys below
# and used to compute each widget's index= on every render, making the
# choice survive a round trip through any other page.
tc, sc, mc = st.columns(3, gap="large")

TERM_OPTIONS = [f"Term_{i}" for i in range(1, 9)]
_persisted_term = st.session_state.get("persisted_term")
_term_index = TERM_OPTIONS.index(_persisted_term) if _persisted_term in TERM_OPTIONS else 0
with tc:
    selected_term = st.selectbox("Academic Term", TERM_OPTIONS, index=_term_index, key="term_select")
st.session_state.persisted_term = selected_term

# Build subject → [manuals] mapping for every subject that has an indexed
# textbook (FAISS index under user_profiles/<term>/) for this term — see
# subject_catalog.build_subject_manuals(). A subject shows here as soon as
# its book is uploaded and indexed; it does NOT wait for question-bank
# coverage in quiz_bank.json, so newly uploaded books are immediately usable
# for the AI Assistant and Study Materials pages. The Adaptive Quiz card
# below still only proceeds once a subject/manual is selected — if a
# subject's QB isn't populated yet, _quiz.py is responsible for surfacing
# that (e.g. "no questions available yet") rather than this page hiding the
# subject outright.
subject_manuals = build_subject_manuals(BASE_DIR, selected_term)
subjects = sorted(subject_manuals.keys()) if subject_manuals else []

_persisted_subject = st.session_state.get("persisted_subject")
_subject_index = subjects.index(_persisted_subject) if _persisted_subject in subjects else 0
with sc:
    # key includes selected_term so this widget resets (rather than keeping a
    # stale value from a previously selected term that isn't a valid option
    # here) the moment the term itself changes within the same page visit.
    selected_subject = st.selectbox(
        "Subject",
        subjects if subjects else ["No Subjects Found"],
        index=_subject_index if subjects else 0,
        key=f"subject_select_{selected_term}"
    )
st.session_state.persisted_subject = selected_subject

# Manuals for selected subject
manual_options = []  # list of (display_name, stem)
if selected_subject in subject_manuals:
    manual_options = subject_manuals[selected_subject]

manual_display_names = [m[0] for m in manual_options] if manual_options else ["No Manuals Found"]
_persisted_manual = st.session_state.get("persisted_manual")
_manual_index = (manual_display_names.index(_persisted_manual)
                 if _persisted_manual in manual_display_names else 0)
with mc:
    # Same reasoning as the Subject widget above — key on term+subject so a
    # manual from a previously selected subject can never leak through.
    selected_manual_display = st.selectbox(
        "Subject Manual", manual_display_names,
        index=_manual_index if manual_options else 0,
        key=f"manual_select_{selected_term}_{selected_subject}"
    )
st.session_state.persisted_manual = selected_manual_display

# Resolve the stem (used downstream as selected_subject equivalent)
selected_manual_stem = None
if manual_options:
    for display, stem in manual_options:
        if display == selected_manual_display:
            selected_manual_stem = stem
            break

# Keep legacy variable names expected by cards / pages
subs = subjects  # truthy check used in quiz card

# ── ALL 4 CARDS — iframe components (immune to Streamlit white-bg injection) ──
CARD_CSS = ("background:#030d1c;border:1px solid rgba(201,164,92,0.28);"
            "border-radius:14px;width:100%;height:196px;"
            "display:flex;flex-direction:column;align-items:center;justify-content:center;"
            "padding:16px 24px;cursor:pointer;position:relative;overflow:hidden;"
            "box-sizing:border-box;transition:transform .28s ease,border-color .28s,box-shadow .28s;")
GF = "https://fonts.googleapis.com/css2?family=Cinzel:wght@700&family=Cormorant+Garamond:ital,wght@1,400&display=swap"

def make_card(cid, title, desc, bar_color, hover_shadow, btn_index):
    return f"""
    <link href="https://fonts.googleapis.com/css2?family=Cinzel:wght@700&family=Cormorant+Garamond:ital,wght@1,400&display=swap" rel="stylesheet">
    <style>*{{margin:0;padding:0;box-sizing:border-box;}}html,body{{background:transparent;}}</style>
    <div id="{cid}" style="{CARD_CSS}">
      <div style="position:absolute;top:0;left:8%;right:8%;height:1px;
                  background:linear-gradient(90deg,transparent,rgba(201,164,92,0.4),transparent);"></div>
      <div style="position:absolute;bottom:0;left:0;right:0;height:4px;border-radius:0 0 14px 14px;
                  background:{bar_color};"></div>
      <div style="font-family:'Cinzel',serif;font-weight:700;font-size:18px;color:#e8c87a;
                  letter-spacing:0.12em;text-transform:uppercase;margin:0 0 8px 0;
                  text-align:center;text-shadow:0 2px 12px rgba(0,0,0,0.9);">{title}</div>
      <div style="font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;
                  color:rgba(245,233,200,0.88);line-height:1.55;text-align:center;max-width:380px;font-size:14.5px;">{desc}</div>
    </div>
    <script>
      (function() {{
        /* Hide all dot trigger buttons in the parent page */
        function hideDots() {{
          try {{
            var btns = window.parent.document.querySelectorAll('button');
            btns.forEach(function(b) {{
              if (b.innerText.trim() === '.') {{
                b.style.cssText = 'display:none!important;width:0!important;height:0!important;min-height:0!important;padding:0!important;margin:0!important;border:none!important;position:absolute!important;overflow:hidden!important;pointer-events:none!important;opacity:0!important;';
                var wrap = b.closest('[data-testid="stButton"]');
                if (wrap) wrap.style.cssText = 'display:none!important;width:0!important;height:0!important;min-height:0!important;overflow:hidden!important;position:absolute!important;';
                var col = b.closest('[data-testid="column"]');
                /* do NOT hide the column itself, only the button wrapper */
              }}
            }});
          }} catch(e) {{}}
        }}
        hideDots();
        new MutationObserver(hideDots).observe(
          window.parent.document.body,
          {{childList:true, subtree:true}}
        );

        /* Card click → trigger parent button by index */
        var c = document.getElementById('{cid}');
        c.onclick = function() {{
          try {{
            var dots = Array.from(window.parent.document.querySelectorAll('button'))
                           .filter(function(b){{ return b.innerText.trim() === '.'; }});
            /* even after hiding, the buttons still exist in DOM and are clickable */
            if (dots[{btn_index}]) dots[{btn_index}].click();
          }} catch(e) {{ console.log('click err', e); }}
        }};
        c.onmouseover = function() {{
          c.style.transform='translateY(-5px)';
          c.style.borderColor='rgba(201,164,92,0.55)';
          c.style.boxShadow='{hover_shadow}';
        }};
        c.onmouseout = function() {{
          c.style.transform='';
          c.style.borderColor='rgba(201,164,92,0.28)';
          c.style.boxShadow='';
        }};
      }})();
    </script>"""

r1c1, r1c2 = st.columns(2, gap="large")
with r1c1:
    components.html(make_card("ai", "AI Learning Assistant",
        "Ask technical questions, get instant AI-powered answers from your course manuals with adaptive depth.",
        "linear-gradient(90deg,#4400aa,#c060ff)","0 24px 60px rgba(110,0,200,0.35)", 0),
        height=200, scrolling=False)
    if st.button(".", key="k_ai"):
        st.session_state.selected_term            = selected_term
        st.session_state.selected_subject         = selected_manual_stem or selected_subject
        st.session_state.selected_subject_display = selected_subject
        st.switch_page("pages/chatbot.py")

with r1c2:
    components.html(make_card("quiz","Adaptive Quiz",
        "Test your knowledge with AI-generated questions that adapt to your performance and subject level.",
        "linear-gradient(90deg,#8b1a00,#ff4500)","0 24px 60px rgba(139,26,0,0.35)", 1),
        height=200, scrolling=False)
    if st.button(".", key="k_quiz"):
        if subs and manual_options and "No Manuals" not in selected_manual_display:
            st.session_state.selected_term            = selected_term
            st.session_state.selected_subject         = selected_manual_stem or selected_subject
            st.session_state.selected_subject_display = selected_subject
            # Clear all quiz state so _quiz.py starts at chapter-selection (step 0)
            for k in ["quiz_step","quiz_chapter","score","current_di","history","quiz_log",
                      "show_explanation","current_question","user_ans","is_correct",
                      "cb_generated_qs","cb_q_index","chatbot_quiz_mode"]:
                st.session_state.pop(k, None)
            st.session_state.quiz_active = True
            st.switch_page("pages/_quiz.py")
        else:
            st.warning("Please select a Subject Manual first.")

r2c1, r2c2 = st.columns(2, gap="large")
with r2c1:
    components.html(make_card("mat","Study Materials",
        "Browse and download your course manuals, reference documents and supplementary study resources.",
        "linear-gradient(90deg,#004499,#1e90ff)","0 24px 60px rgba(0,64,153,0.35)", 2),
        height=200, scrolling=False)
    if st.button(".", key="k_mat"):
        st.session_state.selected_term            = selected_term
        st.session_state.selected_subject         = selected_manual_stem or selected_subject
        st.session_state.selected_subject_display = selected_subject
        st.switch_page("pages/study_materials.py")

with r2c2:
    components.html(make_card("asn","Assignments",
        "View, download and submit assignments given by your instructor. Track submission status and deadlines.",
        "linear-gradient(90deg,#7a4800,#e8a020)","0 24px 60px rgba(200,120,0,0.35)", 3),
        height=200, scrolling=False)
    if st.button(".", key="k_asn"):
        st.switch_page("pages/assignments.py")
